package com.example.splitstory;
import java.io.*;import java.nio.file.*;import java.security.*;import java.security.cert.*;import java.security.spec.*;import java.util.*;import javax.crypto.*;import org.json.*;import android.content.Context;
public class SigningIntegrationHost {
static final Map<String,Key> keyStore=new HashMap<>();static final Map<String,java.security.cert.Certificate> certs=new HashMap<>();
public static class AndroidProvider extends Provider{public AndroidProvider(){super("AndroidKeyStore",1.0,"Host-only Keystore mock");put("KeyStore.AndroidKeyStore",MemoryStore.class.getName());put("KeyGenerator.AES",AES.class.getName());}}
public static class AES extends KeyGeneratorSpi {String alias;protected void engineInit(SecureRandom r){}protected void engineInit(int n,SecureRandom r){}protected void engineInit(AlgorithmParameterSpec p,SecureRandom r){alias=((android.security.keystore.KeyGenParameterSpec)p).alias;}protected SecretKey engineGenerateKey(){try{KeyGenerator g=KeyGenerator.getInstance("AES","SunJCE");g.init(256);SecretKey k=g.generateKey();keyStore.put(alias,k);return k;}catch(Exception e){throw new RuntimeException(e);}}}
public static class MemoryStore extends KeyStoreSpi {public Key engineGetKey(String a,char[]p){return keyStore.get(a);}public java.security.cert.Certificate[] engineGetCertificateChain(String a){return new java.security.cert.Certificate[]{certs.get(a)};}public java.security.cert.Certificate engineGetCertificate(String a){return certs.get(a);}public Date engineGetCreationDate(String a){return new Date();}public void engineSetKeyEntry(String a,Key k,char[]p,java.security.cert.Certificate[]c){keyStore.put(a,k);if(c!=null&&c.length>0)certs.put(a,c[0]);}public void engineSetKeyEntry(String a,byte[]b,java.security.cert.Certificate[]c){}public void engineSetCertificateEntry(String a,java.security.cert.Certificate c){certs.put(a,c);}public void engineDeleteEntry(String a){keyStore.remove(a);certs.remove(a);}public Enumeration<String> engineAliases(){return Collections.enumeration(keyStore.keySet());}public boolean engineContainsAlias(String a){return keyStore.containsKey(a);}public int engineSize(){return keyStore.size();}public boolean engineIsKeyEntry(String a){return keyStore.containsKey(a);}public boolean engineIsCertificateEntry(String a){return certs.containsKey(a);}public String engineGetCertificateAlias(java.security.cert.Certificate c){return "";}public void engineStore(OutputStream o,char[]p){}public void engineLoad(InputStream i,char[]p){}}
static void require(boolean b,String m){if(!b)throw new AssertionError(m);}
public static void main(String[] args)throws Exception{Security.addProvider(new AndroidProvider());File dir=Files.createTempDirectory("creator-native-qa-").toFile();Context a=new Context(new File(dir,"a"));CreatorSigning one=new CreatorSigning(a);CreatorKeys original=one.get("game",true);String pkg=ApkExportEngine.packageName("game",original.cert);a.getSharedPreferences("game-apk-versions",0).edit().putInt(pkg,4).commit();JSONObject backup=new JSONObject(one.backup("game"));require(backup.getString("mode").equals("portable"),"new mode");String sealed=new String(Files.readAllBytes(new File(a.getFilesDir(),"creator-signing/game.key").toPath()),"UTF-8");require(!sealed.contains(backup.getString("key")),"private key leaked on disk");keyStore.clear();certs.clear();Context b=new Context(new File(dir,"b"));CreatorSigning two=new CreatorSigning(b);require(two.restore("game",backup.toString(),8),"restore");CreatorKeys restored=two.get("game",false);require(Arrays.equals(original.cert.getEncoded(),restored.cert.getEncoded()),"cert changed");require(new JSONObject(two.info("game")).getInt("version")==8,"latest APK floor");two.restore("game",backup.toString(),2);require(new JSONObject(two.info("game")).getInt("version")==8,"version downgraded");CreatorKeys foreign=CreatorKeys.generate();JSONObject bad=new JSONObject(backup.toString());bad.put("key",java.util.Base64.getEncoder().encodeToString(foreign.encode()));boolean rejected=false;try{two.restore("game",bad.toString(),8);}catch(Exception e){rejected=true;}require(rejected,"foreign key accepted");require(Arrays.equals(restored.cert.getEncoded(),two.get("game",false).cert.getEncoded()),"valid key overwritten");
// Detect an existing v20/v21 export and retain its non-exportable signer.
keyStore.clear();certs.clear();Context oldContext=new Context(new File(dir,"old"));CreatorKeys old=CreatorKeys.generate();keyStore.put("event-game-export-v1",old.key);certs.put("event-game-export-v1",old.cert);String oldPkg=ApkExportEngine.packageName("old_game",old.cert);oldContext.getSharedPreferences("game-apk-versions",0).edit().putInt(oldPkg,3).commit();CreatorSigning oldSigning=new CreatorSigning(oldContext);JSONObject legacy=new JSONObject(oldSigning.backup("old_game"));require(legacy.getString("mode").equals("legacy")&&!legacy.has("key"),"legacy key should not be exported");require(Arrays.equals(old.cert.getEncoded(),oldSigning.get("old_game",true).cert.getEncoded()),"legacy key changed");keyStore.clear();certs.clear();Context missing=new Context(new File(dir,"missing"));CreatorSigning blocked=new CreatorSigning(missing);blocked.restore("old_game",legacy.toString(),3);rejected=false;try{blocked.get("old_game",true);}catch(Exception e){rejected=true;}require(rejected,"legacy import silently became a new signing identity");
// The actual partition store rejects forged hash filenames and keeps the original.
PartitionStore files=new PartitionStore(new File(dir,"chunks"));String value="real media";StringBuilder hash=new StringBuilder();for(byte x:MessageDigest.getInstance("SHA-256").digest(value.getBytes("UTF-8")))hash.append(String.format("%02x",x&255));JSONObject chunks=new JSONObject();chunks.put(hash.toString(),value);require(files.saveChunks(chunks.toString()),"chunk write");require(files.readChunk(hash.toString()).equals(value),"chunk read");chunks.put(hash.toString(),"forged");require(!files.saveChunks(chunks.toString()),"forged chunk accepted");require(files.readChunk(hash.toString()).equals(value),"forged chunk replaced valid one");require(files.saveIndex("old index"),"index write");require(files.saveIndex("new index"),"second index");require(new String(Files.readAllBytes(new File(dir,"chunks/project.backup.json").toPath()),"UTF-8").equals("old index"),"backup order");Files.write(new File(dir,"chunks/content/"+hash).toPath(),"corrupt".getBytes("UTF-8"));chunks.put(hash.toString(),value);require(files.saveChunks(chunks.toString())&&files.readChunk(hash.toString()).equals(value),"valid backup did not repair corrupt content");System.out.println("PASS actual CreatorSigning with host Keystore/Context adapters: encrypted local key, fresh-device restore, latest-version floor, no downgrade, conflicting-key rejection, legacy signer retention and missing-legacy refusal; actual hashed file writes reject tampering.");}
}
